[8557]={["atomIDs"]={"8557:description:1-65","8557:description:68-160","8557:description:165-229","8557:description:232-306","8557:description:311-346","8557:objective:1-110","8557:objective:113-196"},["editorialVersion"]=2,["endingAtomIDs"]={"8557:completion:1-9","8557:completion:11-35","8557:completion:40-59","8557:completion:61-113"},["opening"]="Keyl Swiftclaw offers to resize a martial drape and fit it with an idol-and-scarab clasp. The promised protection is reserved for someone Revered by the Cenarion Circle.",["pending"]="{actor} would bring the drape, two Onyx Idols, five Silver and five Bone Scarabs.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled the Drape of Unyielding Strength exchange.",["sourceHash"]="19bd43f0a1f4e243462e68521aa3f5c93d93a6961829e52bc551101e493edd37",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
