[8585]={["aftermath"]="Dirge admired the tenderloins and needed a few minutes to devise the remaining preparation for Narain's order.",["atomIDs"]={"8585:description:1-121","8585:description:123-235","8585:description:240-320","8585:description:322-351","8585:description:353-426","8585:description:431-506","8585:objective:1-89"},["bridge"]="The enormous-chicken inquiry had reached Dirge. He proposed Lakmaeran's carcass from the Isle of Dread as a workable substitute, with tenderloins gathered for his own recipe.",["bridgeFrom"]=8584,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"8585:completion:1-47","8585:completion:49-58","8585:completion:63-87","8585:completion:89-104","8585:completion:106-158"},["opening"]="Dirge found a possible answer on the Isle of Dread: Lakmaeran's carcass might pass for Narain's enormous chicken after preparation. Twenty tenderloins from the island's chimaerok would satisfy the cook's own interest.",["pending"]="{actor} would obtain Lakmaeran's Carcass and twenty Chimaerok Tenderloins for Dirge.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Lakmaeran's Carcass and twenty Chimaerok Tenderloins to Dirge.",["sourceClassMask"]="?",["sourceHash"]="6733dbfce28a710a1422cf66e3c0c59beac288f69e15ecc6f9ea4b308d60434f",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
