[8606]={["aftermath"]="Narain acknowledged that the booknappers had been underestimated. The decoy had not supplied the simple conclusion his plan anticipated.",["atomIDs"]={"8606:description:1-12","8606:description:14-43","8606:description:45-117","8606:description:119-192","8606:description:197-227","8606:description:232-258","8606:description:260-348","8606:description:353-406","8606:description:408-462","8606:description:464-504","8606:objective:1-143"},["bridge"]="The ransom had reached Narain, who answered with a deception. Clothes and a bag of rocks would send a substitute to the Winterspring drop instead of the demanded gold.",["bridgeFrom"]=8598,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"8606:completion:1-53"},["opening"]="Narain proposed a false ransom drop in Winterspring. His kit held clothes for impersonating him and a sack of rocks in place of payment, turning the booknappers' instructions into a trap.",["pending"]="{actor} would place the disguised ransom bag at the Winterspring drop point.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the Bag of Gold drop assignment in Winterspring.",["sourceClassMask"]="?",["sourceHash"]="87766da4743951248cd200a77f18e3b25c7712f8e9e63a5c0a97f2f345facfaf",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
