[8620]={["aftermath"]="Narain accepted the reconstructed book and marveled at the persistence required to recover it. The translation work once blocked by its loss could now continue.",["atomIDs"]={"8620:description:1-20","8620:description:22-72","8620:description:74-158","8620:description:160-205","8620:description:210-348","8620:description:350-471","8620:objective:1-196"},["bridge"]="The decoy exchange had ended without restoring the book. Narain now named Doctor Weavil and a note describing eight scattered chapters, leaving recovery and magical rebinding as the remaining answer.",["bridgeFrom"]=8606,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"8620:completion:1-10","8620:completion:12-55","8620:completion:57-85","8620:completion:87-150","8620:completion:155-182","8620:completion:184-221"},["opening"]="Narain named Doctor Weavil as his enemy behind the booknapping and blamed the Winterspring outcome for the book's destruction. A note said its eight chapters were scattered, leaving a magical binding as the means to rebuild it.",["pending"]="{actor} planned to recover eight chapters and bind Draconic for Dummies: Volume II.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the reassembled Draconic for Dummies: Volume II to Narain.",["sourceClassMask"]="?",["sourceHash"]="baed6f550321c8133be452d80ef36c60728241328c5639d691ed715ef892b7d0",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
