[8773]={["aftermath"]="Mar'alith had heard favorable reports of the contribution and urged continued work.",["atomIDs"]={"8773:description:1-68","8773:description:71-121","8773:description:124-185","8773:objective:1-94","8773:objective:97-172"},["endingAtomIDs"]={"8773:completion:1-63","8773:completion:65-116"},["opening"]="The western hive assault had called for reinforcements. This combat paper assigned reavers as the specific target before the return to Mar'alith.",["pending"]="{actor} planned to confront thirty reavers and return the briefing.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the reaver assignment.",["sourceHash"]="e6e8875fcac2c98e9e728d7ec78e3d119468dad6028c989c5cf7db4347b8d233",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
